dtsPropsFor.Button:
/** primary is the one next step on a screen; secondary is everything else. Default primary. */
  kind?: "primary" | "secondary";
  /** Shows a spinner and busyLabel, and sets aria-disabled. */
  busy?: boolean;
  /** Text shown while busy, e.g. "Paying…". Falls back to children. */
  busyLabel?: string;
  children?: React.ReactNode;
  type?: "button" | "submit" | "reset";
  name?: string;
  value?: string;
  onClick?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  /** Plus every other native <button> attribute. */
  [attribute: string]: unknown;

dtsPropsFor.Notice:
/** wait = waiting for the helper; danger = a real failure; neutral = a helper said no, or nothing found. */
  tone: "wait" | "danger" | "neutral";
  children: React.ReactNode;

dtsPropsFor.Summary:
/** Item name, shown above the amount. */
  title?: string;
  /** Amount in US cents; rendered as $29.99. */
  cents: number;
  /** One short line under the amount, e.g. "From amazon.com". */
  note?: string;

dtsPropsFor.ItemPicker:
/** Prices are in US cents. */
  items: { id: string; name: string; cents: number }[];
  /** id of the heading that names the choice. */
  labelledBy: string;
  /** id of the item checked at first. */
  picked?: string;
  /** Shows "Pick one of the three first." under the list. */
  error?: boolean;

dtsPropsFor.ListingPicker:
/** Prices are in US cents. what, why and watch are one sentence each. */
  listings: { id: string; name: string; cents: number; shop: string; url: string; imageUrl?: string; what: string; why: string; watch: string }[];
  /** id of the heading that names the choice. */
  labelledBy: string;
  /** id of the listing checked at first. */
  picked?: string;
  /** Shows "Pick one first." under the list. */
  error?: boolean;
